import './App.css';
import Home from './Pages/Home/index.js';
import About from './Pages/AboutMe/index.js';
import Timeline from './Pages/Timeline/timeline.js';
import Projects from './Pages/Projects/index.js';
import Header from './Components/Header/index.js';
import Footer from './Components/Footer/index.js';
import { Routes, Route, HashRouter  } from "react-router-dom";
import React from 'react';
import colors from './Components/Constants/colorscheme';
import { ThemeProvider, createTheme, styled } from '@mui/material/styles';
import { Box } from '@mui/material';

const HeaderSpacing = styled(Box)(({theme})=>({
  ...theme.mixins.toolbar,
}));

const customDarkTheme  = () => ({
  palette: {
    breakpoints: {
      values: {
        xs: 0,
        sm: 600,
        md: 1000,
        lg: 1200,
        xl: 1536,
      },
    },
    primary: {
      main: colors[1],
    },
    secondary: {
      main: colors[2],
    },
    background: {
      default: colors[2],
      paper: colors[1],
    },
    text: {
      primary: colors[2],
      secondary: colors[2],
    },
  },
});

const customTheme = createTheme(customDarkTheme());

function App() {
  return (
    <ThemeProvider theme={customTheme}>
      <HashRouter basename="/">
      <div className="Main" style={{backgroundColor: colors[1]}}>
        <div>
          <Header/>
        </div>
        <div className='pageContent'>
          <HeaderSpacing/>
          <Routes>
            <Route path='/' element={<Home/>}/>
            <Route path='/About' element={<About/>}/>
            <Route path='/Timeline' element={<Timeline/>}/>
            <Route path='/Projects' element={<Projects/>}/>
          </Routes>
        </div>
        <div className='footerContent'>
          <Footer/>
        </div>
      </div>
      </HashRouter>
    </ThemeProvider>
  );
}

export default App;
